entries.syntax:
void *malloc(size_t size);
void *calloc(size_t n, size_t size);
void *realloc(void *ptr, size_t size);
void free(void *ptr);

entries.example:
int *v = calloc(16, sizeof(int));
if (v == NULL) return 1;
int *tmp = realloc(v, 32 * sizeof(int));
if (tmp != NULL) v = tmp;
free(v);

