entries.example:
typedef struct { float real, imag; } Complex;
Complex c = {1.5f, -2.3f};
Complex *pc = &c;
pc->real = 5.0f;   /* same as (*pc).real = 5.0f */

char buf[6];
strcpy(buf, "Hello");        /* fits exactly: 5 + 1 */
char *copy = malloc(strlen(buf) + 1);

